const factors = $('Obtener rating_factors del producto').item.json.rating_factors || [];
const trigger = $('Entrada (tool)').item.json;
let inputs = {};
try { inputs = JSON.parse(trigger.inputs_json || '{}'); } catch (e) { inputs = {}; }

const missing = factors.filter(f => inputs[f] === undefined || inputs[f] === null || inputs[f] === '');

return [{
  json: {
    ok: missing.length === 0,
    missing_fields: missing,
    inputs,
    contact_chat_id: trigger.contact_chat_id,
    product_code: trigger.product_code
  }
}];

const line = $json;
const apiOk = line.statusCode && line.statusCode < 400 && line.body?.premium;
if (apiOk) return { json: { ...line, premium: line.body.premium, source: 'api' } };
// Fallback controlado: tarifa de tabla si existe, marcada como estimate
if (line.base_premium != null) return { json: { ...line, premium: line.base_premium, source: 'estimate' } };
return { json: { ...line, premium: null, source: 'unavailable' } };

const line = $json;
if (line.base_premium != null) {
  return { json: { ...line, premium: line.base_premium, source: line.source || 'manual' } };
}
return { json: { ...line, premium: null, source: 'unavailable' } };

const lines = $input.all().map(i => i.json);
const available = lines.filter(l => l.premium != null);
available.sort((a, b) => a.premium - b.premium);
available.forEach((l, idx) => { l.rank = idx + 1; });
lines.forEach(l => {
  if (l.premium != null) {
    l.commission_amount = Math.round((l.premium * (l.commission_pct || 0) / 100) * 100) / 100;
  } else {
    l.commission_amount = null;
    l.rank = null;
    l.unavailable_reason = l.source === 'unavailable' ? 'sin_tarifa_vigente' : null;
  }
});
return lines.map(l => ({ json: l }));

